using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Web.Script.Serialization;using ReplierDesktop;
public static class SceneWriterActualProbe {
 public static int Main(string[] a){try{var json=new JavaScriptSerializer{MaxJsonLength=16*1024*1024};var doc=SceneMaterial.Json(File.ReadAllText(Path.Combine(a[0],"extension/data/replier-grounded-checks/scene-final-"+a[1]+".json")));var runs=(object[])CaptionService.Get(doc,"runs");var batches=(object[])CaptionService.Get(CaptionService.Get(runs[0],"result"),"Batches");var rows=(object[])CaptionService.Get(CaptionService.Get(batches[0],"Result"),"Comments");var material=rows.Select(r=>new{key=(string)CaptionService.Get(r,"CueId"),value=(string)CaptionService.Get(r,"Material")}).GroupBy(r=>r.key).ToDictionary(g=>g.Key,g=>g.First().value);var content=new ContentStore(Path.Combine(a[0],"extension/data/replier/content")).Load(a[1]);var video=json.Deserialize<Video>(json.Serialize(CaptionService.Get(doc,"video")));var results=new List<object>();foreach(string name in DualCommentService.Models)using(var m=new LocalModel(Path.Combine(a[0],"extension/.runtime/replier-llm"),name)){var result=new CommentService(m).Generate(video,content,CancellationToken.None,true,material).GetAwaiter().GetResult();foreach(var c in result.Comments)Console.WriteLine(name+" | "+c.Text);results.Add(new{model=name,result=result});m.Unload().GetAwaiter().GetResult();}File.WriteAllText(Path.Combine(a[0],"extension/data/replier-grounded-checks/scene-simple-writer-"+a[1]+".json"),json.Serialize(results));return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
